SELECT th.tier, SUM(oi.line_total_bdt) FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN seller_tier_history th ON th.seller_id = oi.seller_id AND th.valid_to = DATE '9999-12-31' WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-04-01' AND DATE '2024-06-30' AND th.tier IN ('gold', 'silver') GROUP BY 1
